SELECT COUNT(*)
FROM schedule
WHERE class_id = #{classId}
  AND day_of_week = #{dayOfWeek}
  AND period = #{period}
  AND semester = #{semester}
  AND is_deleted = 0

    AND id != #{excludeId}

SELECT COUNT(*)
FROM schedule
WHERE teacher_id = #{teacherId}
  AND day_of_week = #{dayOfWeek}
  AND period = #{period}
  AND semester = #{semester}
  AND is_deleted = 0

    AND id != #{excludeId}

SELECT COUNT(*)
FROM schedule
WHERE room_number = #{roomNumber}
  AND day_of_week = #{dayOfWeek}
  AND period = #{period}
  AND semester = #{semester}
  AND is_deleted = 0

    AND id != #{excludeId}

SELECT id, class_id, course_id, teacher_id, day_of_week, period,
       room_number, semester, create_time, update_time, is_deleted
FROM schedule
WHERE class_id = #{classId}
  AND semester = #{semester}
  AND is_deleted = 0

    AND day_of_week IN

        #{day}


ORDER BY day_of_week, period
